export type AddWorkItemLinkRequestlinkType = 'System.LinkTypes.Related'|'System.LinkTypes.Hierarchy-Forward'|'System.LinkTypes.Hierarchy-Reverse'|'System.LinkTypes.Dependency-Forward'|'System.LinkTypes.Dependency-Reverse'|'System.LinkTypes.Duplicate-Forward'|'System.LinkTypes.Duplicate-Reverse'|'Microsoft.VSTS.Common.TestedBy-Forward'|'Microsoft.VSTS.Common.TestedBy-Reverse'|'Microsoft.VSTS.TestCase.SharedStepReferencedBy-Forward'|'Microsoft.VSTS.TestCase.SharedStepReferencedBy-Reverse'|'Microsoft.VSTS.TestCase.SharedParameterReferencedBy-Forward'|'Microsoft.VSTS.TestCase.SharedParameterReferencedBy-Reverse'|'Microsoft.VSTS.Common.Affects-Forward'|'Microsoft.VSTS.Common.Affects-Reverse'|'Hyperlink';

export interface AddWorkItemLinkRequest {
  // Relation type for the link. Defaults to 'System.LinkTypes.Related' when omitted.
  linkType: AddWorkItemLinkRequestlinkType;
  // Absolute URL of the link target. Must be an absolute URI and match the expectations for the selected Link Type.
  targetUrl: string;
  // Optional comment stored alongside the link.
  comment?: string;
}

export type DeleteWorkItemLinkRequestlinkType = 'System.LinkTypes.Related'|'System.LinkTypes.Hierarchy-Forward'|'System.LinkTypes.Hierarchy-Reverse'|'System.LinkTypes.Dependency-Forward'|'System.LinkTypes.Dependency-Reverse'|'System.LinkTypes.Duplicate-Forward'|'System.LinkTypes.Duplicate-Reverse'|'Microsoft.VSTS.Common.TestedBy-Forward'|'Microsoft.VSTS.Common.TestedBy-Reverse'|'Microsoft.VSTS.TestCase.SharedStepReferencedBy-Forward'|'Microsoft.VSTS.TestCase.SharedStepReferencedBy-Reverse'|'Microsoft.VSTS.TestCase.SharedParameterReferencedBy-Forward'|'Microsoft.VSTS.TestCase.SharedParameterReferencedBy-Reverse'|'Microsoft.VSTS.Common.Affects-Forward'|'Microsoft.VSTS.Common.Affects-Reverse'|'Hyperlink';

export interface DeleteWorkItemLinkRequest {
  // Zero-based relation identifier (attributes.relationId) or array position from the work item response.
  linkId?: number;
  // Absolute URL of the link to delete when a relation identifier is not provided.
  workItemLinkToRemove?: string;
  // Relation type (rel) of the link to delete when matching by URL.
  linkType?: DeleteWorkItemLinkRequestlinkType;
}

export interface CreateWorkItemCommentRequest {
  // The text of the comment.
  text: string;
}

export interface WorkItemResponse {
  // The unique id of the work item.
  id?: number;
  // The revision count of the work item.
  rev?: number;
  // The URL of the work item.
  url?: string;
  fields?: WorkItemFields;
  // The relations associated with the work item.
  relations?: {
   // Relation type identifier, for example 'System.LinkTypes.Related'.
   rel?: string;
   // Target URL for the relation.
   url?: string;
   // Additional metadata about the relation, including its zero-based relationId.
   attributes?: {
     // Zero-based position of this relation within the response array.
     relationId?: number;
     // Indicates whether the relation is locked.
     isLocked?: boolean;
     // Optional comment stored alongside the relation.
     comment?: string;
     // Display name for the relation when provided.
     name?: string;
   };
 }[];
  // Hypermedia links related to the work item.
  _links?: Record<string, unknown>;
}

